import AppKit
import CoreGraphics
import SwiftUI

/// Menu bar tray icon: a double-star monochrome silhouette. The geometry comes from the
/// two star paths in Assets/sparkle/sparkle-blue.svg (24×24 viewBox), generated by
/// Scripts/svg-path-to-swift.py—do not hand-edit it; to change the icon, edit the SVG
/// and regenerate.
///
/// Why the detour through NSImage: tested on macOS 27, a Shape + .fill view inside a
/// MenuBarExtra label does not render at all (SF Symbols, text, and template NSImages
/// all work; only Shape does not), so the paths are drawn into an isTemplate NSImage
/// and handed to Image(nsImage:)—the same template-image channel as an SF Symbol,
/// which the system automatically colors black or white according to the menu bar's
/// light/dark appearance, with no need for separate day/dark variants. The vector
/// paths are rasterized at 2x pixels, so they stay sharp on Retina.
struct MenuBarIcon: View {
    /// Point size in the menu bar. The menu bar is 24pt high; 16~18 works well next to text.
    var pointSize: CGFloat = 17

    var body: some View {
        Image(nsImage: Self.templateImage(pointSize: pointSize))
    }

    /// Double-star paths -> template image: black silhouette + transparent channel; after
    /// isTemplate the system takes only the alpha and colors it according to the menu
    /// bar's light/dark appearance. Drawn at 2x pixels; rebuilt on every body evaluation
    /// (a few dozen microseconds—the label only redraws when the values refresh, so a
    /// cache and a concurrency exemption are not worth introducing for it).
    /// `MenuBarStatsImage`'s fallback also comes through here (cases that emit only the
    /// icon, no text).
    static func templateImage(pointSize: CGFloat) -> NSImage {
        let pixels = Int((pointSize * 2).rounded())
        let fallback = NSImage(size: NSSize(width: pointSize, height: pointSize))
        let colorSpace = CGColorSpaceCreateDeviceRGB()
        guard let context = CGContext(
            data: nil,
            width: pixels,
            height: pixels,
            bitsPerComponent: 8,
            bytesPerRow: 0,
            space: colorSpace,
            bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue
        ) else { return fallback }

        // CG bitmap contexts are y-up, SVG paths are y-down; flip first, then draw
        context.translateBy(x: 0, y: CGFloat(pixels))
        context.scaleBy(x: 1, y: -1)
        // 24×24 design space -> pixel size
        var transform = CGAffineTransform(scaleX: CGFloat(pixels) / 24, y: CGFloat(pixels) / 24)
        context.setFillColor(CGColor(gray: 0, alpha: 1))

        // The two stars are filled separately: in the SVG they are two independent path
        // elements, each filled with nonzero winding; when merged into one path the two
        // subpaths wind in opposite directions, the overlapping area's winding number
        // cancels out to 0, and a cross-shaped hole gets punched out of the middle of
        // the front star (tested).
        for path in [MenuBarStarPath.back, MenuBarStarPath.front] {
            context.addPath(path.copy(using: &transform) ?? path)
            context.fillPath()
        }

        guard let cgImage = context.makeImage() else { return fallback }
        let image = NSImage(cgImage: cgImage, size: NSSize(width: pointSize, height: pointSize))
        image.isTemplate = true
        return image
    }
}

/// The two double-star paths, 24×24 design space, for MenuBarIcon to rasterize.
/// They do not change after initialization; Swift guarantees lazy initialization runs
/// only once (thread-safe), so they can be treated as immutable globals; CGPath is not
/// Sendable, so an explicit exemption is made under strict concurrency.
enum MenuBarStarPath {
    /// Back star: a small four-pointed star + small cross, the one partly covered by the front star in the original SVG.
    nonisolated(unsafe) static let back: CGPath = {
        let path = CGMutablePath()
        path.move(to: CGPoint(x: 13, y: 9.00531))
        path.addCurve(to: CGPoint(x: 14, y: 10.0053), control1: CGPoint(x: 13.5522, y: 9.00531), control2: CGPoint(x: 13.9999, y: 9.45308))
        path.addLine(to: CGPoint(x: 14, y: 12.0053))
        path.addLine(to: CGPoint(x: 16, y: 12.0053))
        path.addCurve(to: CGPoint(x: 17, y: 13.0053), control1: CGPoint(x: 16.5522, y: 12.0053), control2: CGPoint(x: 16.9999, y: 12.4531))
        path.addCurve(to: CGPoint(x: 16, y: 14.0053), control1: CGPoint(x: 16.9998, y: 13.5574), control2: CGPoint(x: 16.5521, y: 14.0053))
        path.addLine(to: CGPoint(x: 14, y: 14.0053))
        path.addLine(to: CGPoint(x: 14, y: 16.0053))
        path.addCurve(to: CGPoint(x: 13, y: 17.0053), control1: CGPoint(x: 13.9998, y: 16.5574), control2: CGPoint(x: 13.5521, y: 17.0053))
        path.addCurve(to: CGPoint(x: 12, y: 16.0053), control1: CGPoint(x: 12.4479, y: 17.0053), control2: CGPoint(x: 12.0002, y: 16.5574))
        path.addLine(to: CGPoint(x: 12, y: 14.0053))
        path.addLine(to: CGPoint(x: 10, y: 14.0053))
        path.addCurve(to: CGPoint(x: 9, y: 13.0053), control1: CGPoint(x: 9.44791, y: 14.0053), control2: CGPoint(x: 9.00025, y: 13.5574))
        path.addCurve(to: CGPoint(x: 10, y: 12.0053), control1: CGPoint(x: 9.00007, y: 12.4531), control2: CGPoint(x: 9.4478, y: 12.0054))
        path.addLine(to: CGPoint(x: 12, y: 12.0053))
        path.addLine(to: CGPoint(x: 12, y: 10.0053))
        path.addCurve(to: CGPoint(x: 13, y: 9.00531), control1: CGPoint(x: 12.0001, y: 9.45311), control2: CGPoint(x: 12.4478, y: 9.00536))
        path.closeSubpath()
        path.move(to: CGPoint(x: 6.07031, y: 1.34125))
        path.addCurve(to: CGPoint(x: 7.92969, y: 1.34125), control1: CGPoint(x: 6.4044, y: 0.499912), control2: CGPoint(x: 7.59575, y: 0.499853))
        path.addLine(to: CGPoint(x: 9.25, y: 4.66937))
        path.addCurve(to: CGPoint(x: 9.33008, y: 4.74847), control1: CGPoint(x: 9.26453, y: 4.70571), control2: CGPoint(x: 9.29373, y: 4.73396))
        path.addLine(to: CGPoint(x: 12.6592, y: 6.07074))
        path.addCurve(to: CGPoint(x: 12.6592, y: 7.92914), control1: CGPoint(x: 13.5005, y: 6.40477), control2: CGPoint(x: 13.5005, y: 7.59509))
        path.addLine(to: CGPoint(x: 9.33008, y: 9.2514))
        path.addCurve(to: CGPoint(x: 9.25, y: 9.33051), control1: CGPoint(x: 9.29374, y: 9.2659), control2: CGPoint(x: 9.26454, y: 9.29419))
        path.addLine(to: CGPoint(x: 7.92969, y: 12.6586))
        path.addCurve(to: CGPoint(x: 6.07031, y: 12.6586), control1: CGPoint(x: 7.59575, y: 13.5), control2: CGPoint(x: 6.4044, y: 13.5))
        path.addLine(to: CGPoint(x: 4.74902, y: 9.33051))
        path.addCurve(to: CGPoint(x: 4.66895, y: 9.2514), control1: CGPoint(x: 4.73446, y: 9.29418), control2: CGPoint(x: 4.70531, y: 9.26588))
        path.addLine(to: CGPoint(x: 1.34082, y: 7.92914))
        path.addCurve(to: CGPoint(x: 1.34082, y: 6.07074), control1: CGPoint(x: 0.49956, y: 7.59509), control2: CGPoint(x: 0.49956, y: 6.40479))
        path.addLine(to: CGPoint(x: 4.66895, y: 4.74847))
        path.addCurve(to: CGPoint(x: 4.74902, y: 4.66937), control1: CGPoint(x: 4.70533, y: 4.73399), control2: CGPoint(x: 4.73447, y: 4.70572))
        path.addLine(to: CGPoint(x: 6.07031, y: 1.34125))
        path.closeSubpath()
        return path
    }()

    /// Front star: the large four-pointed star forming the frosted-glass body.
    nonisolated(unsafe) static let front: CGPath = {
        let path = CGMutablePath()
        path.move(to: CGPoint(x: 16.6562, y: 9.21226))
        path.addLine(to: CGPoint(x: 14.3939, y: 3.51196))
        path.addCurve(to: CGPoint(x: 11.6056, y: 3.51172), control1: CGPoint(x: 13.893, y: 2.24987), control2: CGPoint(x: 12.1067, y: 2.24971))
        path.addLine(to: CGPoint(x: 9.34194, y: 9.21226))
        path.addCurve(to: CGPoint(x: 9.21226, y: 9.34194), control1: CGPoint(x: 9.31834, y: 9.27153), control2: CGPoint(x: 9.27153, y: 9.31834))
        path.addLine(to: CGPoint(x: 3.51085, y: 11.6059))
        path.addCurve(to: CGPoint(x: 3.51085, y: 14.3941), control1: CGPoint(x: 2.24896, y: 12.107), control2: CGPoint(x: 2.24896, y: 13.893))
        path.addLine(to: CGPoint(x: 9.21226, y: 16.6581))
        path.addCurve(to: CGPoint(x: 9.34194, y: 16.7877), control1: CGPoint(x: 9.27153, y: 16.6817), control2: CGPoint(x: 9.31834, y: 16.7285))
        path.addLine(to: CGPoint(x: 11.6055, y: 22.4883))
        path.addCurve(to: CGPoint(x: 14.3939, y: 22.488), control1: CGPoint(x: 12.1067, y: 23.7503), control2: CGPoint(x: 13.8929, y: 23.7501))
        path.addLine(to: CGPoint(x: 16.6562, y: 16.7877))
        path.addCurve(to: CGPoint(x: 16.7868, y: 16.6581), control1: CGPoint(x: 16.6799, y: 16.7283), control2: CGPoint(x: 16.7273, y: 16.6816))
        path.addLine(to: CGPoint(x: 22.4888, y: 14.3941))
        path.addCurve(to: CGPoint(x: 22.4888, y: 11.6059), control1: CGPoint(x: 23.7507, y: 13.8931), control2: CGPoint(x: 23.7507, y: 12.1069))
        path.addLine(to: CGPoint(x: 16.7868, y: 9.34194))
        path.addCurve(to: CGPoint(x: 16.6562, y: 9.21226), control1: CGPoint(x: 16.7273, y: 9.3184), control2: CGPoint(x: 16.6799, y: 9.27173))
        path.closeSubpath()
        return path
    }()
}
